template <unsigned N> struct priority_tag : priority_tag<N - 1> {};
template <> struct priority_tag<0> {};

template <class T> auto size_hint(const T& v, priority_tag<2>) -> decltype(v.size()) { return v.size(); }
template <class T> auto size_hint(const T& v, priority_tag<1>) -> decltype(std::distance(std::begin(v), std::end(v)));
template <class T> size_t size_hint(const T&, priority_tag<0>) { return 0; }   // unconstrained fallback

template <class T> size_t size_hint(const T& v) { return size_hint(v, priority_tag<2>{}); }

template <std::random_access_iterator I>
void advance_(I& it, int n) { it += n; }

template <std::bidirectional_iterator I>
void advance_(I& it, int n) { /* step both ways */ }

template <std::input_iterator I>
void advance_(I& it, int n) { while (n-- > 0) ++it; }
